export interface ConnectorConfig {
  /** Notion integration token (Bearer). Load from NOTION_API_KEY env var. */
  notionApiKey: string
  /** Notion database ID for the pre-existing 'Signed' database. */
  notionDatabaseId: string
  /** Optional Pipedrive Won stage ID. If provided and the webhook contains stage_id, validates the deal moved to this stage. */
  pipedriveWonStageId?: number
  /** Injected fetch for testing. Defaults to global fetch. */
  fetch?: typeof fetch
}

export interface PipedriveDealWonPayload {
  /** Deal title. */
  title: string
  /** Deal value as a float. */
  value: number
  /** Pipedrive user ID of the deal owner. */
  owner_id: number
  /** ISO timestamp when the deal was closed. */
  close_time: string
  /** Optional stage ID from the webhook payload. */
  stage_id?: number
}

export interface HandleResult {
  /** Notion page ID of the created page. */
  pageId: string
}

export async function handle(payload: PipedriveDealWonPayload, config: ConnectorConfig): Promise<HandleResult> {
  // Validate required fields
  if (payload.title === undefined || payload.title === null || payload.title === '') {
    throw new Error('Missing required field: title')
  }
  if (payload.value === undefined || payload.value === null) {
    throw new Error('Missing required field: value')
  }
  if (payload.owner_id === undefined || payload.owner_id === null) {
    throw new Error('Missing required field: owner_id')
  }
  if (payload.close_time === undefined || payload.close_time === null || payload.close_time === '') {
    throw new Error('Missing required field: close_time')
  }

  // Verify won stage if configured and stage_id present in payload
  if (config.pipedriveWonStageId !== undefined && payload.stage_id !== undefined) {
    if (payload.stage_id !== config.pipedriveWonStageId) {
      throw new Error(`Deal stage_id ${payload.stage_id} does not match configured won stage ID ${config.pipedriveWonStageId}`)
    }
  }

  // Map fields to Notion page properties
  const notionPayload = {
    parent: {
      database_id: config.notionDatabaseId
    },
    properties: {
      'Deal Name': {
        title: [
          {
            text: {
              content: payload.title
            }
          }
        ]
      },
      'Deal Value': {
        number: payload.value
      },
      'Owner': {
        people: [
          {
            object: 'user',
            id: String(payload.owner_id)
          }
        ]
      },
      'Close Date': {
        date: {
          start: payload.close_time.split('T')[0]
        }
      }
    }
  }

  const fetchImpl = config.fetch ?? globalThis.fetch
  const response = await fetchImpl('https://api.notion.com/v1/pages', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.notionApiKey}`,
      'Content-Type': 'application/json',
      'Notion-Version': '2022-06-28'
    },
    body: JSON.stringify(notionPayload)
  })

  if (!response.ok) {
    throw new Error(`Notion API error: ${response.status} ${response.statusText} at POST https://api.notion.com/v1/pages`)
  }

  const result = await response.json() as { id: string }
  return { pageId: result.id }
}

import { describe, it, expect, vi } from 'vitest'
