  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      notionApiKey: 'test-notion-key',
      notionDatabaseId: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as PipedriveDealWonPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.pageId).toBe('3c90c3cc-0d44-4b50-8888-8dd25736052a')
  })
})

describe('handle', () => {
  it('happy path: creates Notion page with correct field mapping', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://api.notion.com/v1/pages')
      expect(req.headers.get('authorization')).toBe('Bearer test-notion-key')
      expect(req.headers.get('notion-version')).toBe('2022-06-28')
      const body = req.json as Record<string, unknown>
      expect(body.parent).toEqual({ database_id: 'db-123' })
      expect(body.properties['Deal Name'].title[0].text.content).toBe('Sample Org deal')
      expect(body.properties['Deal Value'].number).toBe(100)
      expect(body.properties['Owner'].people[0]).toEqual({ object: 'user', id: '12415231' })
      expect(body.properties['Close Date'].date.start).toBe('2022-11-24')
      return jsonResponse({ id: 'page-456', object: 'page', created_time: '2023-01-01T00:00:00.000Z' })
    })

    const payload: PipedriveDealWonPayload = {
      title: 'Sample Org deal',
      value: 100,
      owner_id: 12415231,
      close_time: '2022-11-24T13:18:55Z'
    }
    const config: ConnectorConfig = {
      notionApiKey: 'test-notion-key',
      notionDatabaseId: 'db-123',
      fetch
    }

    const result = await handle(payload, config)
    expect(result.pageId).toBe('page-456')
    expect(calls.length).toBe(1)
  })

  it('auth mechanism: sends Bearer token in Authorization header', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.headers.get('authorization')).toBe('Bearer secret-notion-token')
      return jsonResponse({ id: 'page-1' })
    })

    await handle(
      { title: 't', value: 1, owner_id: 2, close_time: '2023-01-01T00:00:00Z' },
      { notionApiKey: 'secret-notion-token', notionDatabaseId: 'db', fetch }
