    const { fetch } = fakeFetch(() => jsonResponse({}))
    await expect(
      handle(
        { title: 't', value: 1, owner_id: undefined as unknown as number, close_time: '2023-01-01T00:00:00Z' },
        { notionApiKey: 'k', notionDatabaseId: 'db', fetch }
      )
    ).rejects.toThrow('Missing required field: owner_id')
  })

